// SPDX-License-Identifier: BSD-2-Clause
/*
 * Copyright (c) 2021, STMicroelectronics - All Rights Reserved
 *
 * Crypto authenc interface implementation to enable HW driver.
 */
#include <assert.h>
#include <crypto/crypto.h>
#include <crypto/crypto_impl.h>
#include <drvcrypt.h>
#include <drvcrypt_authenc.h>
#include <kernel/panic.h>
#include <malloc.h>
#include <utee_defines.h>
#include <util.h>

static const struct crypto_authenc_ops authenc_ops;

/*
 * Returns the reference to the driver context
 *
 * @ctx    Reference the API context pointer
 */
static struct crypto_authenc *to_authenc_ctx(struct crypto_authenc_ctx *ctx)
{
	assert(ctx && ctx->ops == &authenc_ops);

	return container_of(ctx, struct crypto_authenc, authenc_ctx);
}

/*
 * Free authenc context
 *
 * @ctx    Reference the API context pointer
 */
static void authenc_free_ctx(struct crypto_authenc_ctx *ctx)
{
	struct crypto_authenc *authenc = to_authenc_ctx(ctx);

	if (authenc->op && authenc->op->free_ctx)
		authenc->op->free_ctx(authenc->ctx);

	free(authenc);
}

/*
 * Copy authenc context
 *
 * @dst_ctx  [out] Reference the API context pointer destination
 * @src_ctx  Reference the API context pointer source
 */
static void authenc_copy_state(struct crypto_authenc_ctx *dst_ctx,
			       struct crypto_authenc_ctx *src_ctx)
{
	struct crypto_authenc *authenc_src = to_authenc_ctx(src_ctx);
	struct crypto_authenc *authenc_dst = to_authenc_ctx(dst_ctx);

	if (authenc_src->op && authenc_src->op->copy_state)
		authenc_src->op->copy_state(authenc_dst->ctx, authenc_src->ctx);
}

/*
 * Initialization of the authenc operation
 *
 * @ctx         Reference the API context pointer
 * @mode        Operation mode
 * @key         Key
 * @key_len     Length of the key
 * @nonce       Nonce
 * @nonce_len   Length of the nonce
 * @tag_len     Length of the requested tag
 * @aad_len     Length of the associated authenticated data
 * @payload_len Length of payload
 */
static TEE_Result authenc_init(struct crypto_authenc_ctx *ctx,
			       TEE_OperationMode mode, const uint8_t *key,
			       size_t key_len, const uint8_t *nonce,
			       size_t nonce_len, size_t tag_len, size_t aad_len,
			       size_t payload_len)
{
	TEE_Result ret = TEE_ERROR_NOT_IMPLEMENTED;
	struct crypto_authenc *authenc = to_authenc_ctx(ctx);

	if ((!key && key_len) || (!nonce && nonce_len)) {
		CRYPTO_TRACE("One of the key is not correct");
		CRYPTO_TRACE("key   @%p-%zu bytes", key, key_len);
		CRYPTO_TRACE("nonce @%p-%zu bytes", nonce, nonce_len);
		return TEE_ERROR_BAD_PARAMETERS;
	}

	if (authenc->op && authenc->op->init) {
		struct drvcrypt_authenc_init dinit = {
			.ctx = authenc->ctx,
			.encrypt = (mode == TEE_MODE_ENCRYPT),
			.key.data = (uint8_t *)key,
			.key.length = key_len,
			.nonce.data = (uint8_t *)nonce,
			.nonce.length = nonce_len,
			.tag_len = tag_len,
			.aad_len = aad_len,
			.payload_len = payload_len,
		};

		ret = authenc->op->init(&dinit);
	}

	CRYPTO_TRACE("authenc ret 0x%" PRIx32, ret);
	return ret;
}

/*
 * Update Additional Authenticated Data part of the authenc operation
 *
 * @ctx        Reference the API context pointer
 * @data       Data to authenticate without encrypt/decrypt (AAD)
 * @len        AAD length in bytes
 */
static TEE_Result authenc_update_aad(struct crypto_authenc_ctx *ctx,
				     const uint8_t *data, size_t len)
{
	TEE_Result ret = TEE_ERROR_NOT_IMPLEMENTED;
	struct crypto_authenc *authenc = to_authenc_ctx(ctx);

	if (!data && len) {
		CRYPTO_TRACE("Bad data @%p-%zu bytes", data, len);
		return TEE_ERROR_BAD_PARAMETERS;
	}

	if (authenc->op && authenc->op->update_aad) {
		struct drvcrypt_authenc_update_aad dupdate = {
			.ctx = authenc->ctx,
			.aad.data = (uint8_t *)data,
			.aad.length = len,
		};

		ret = authenc->op->update_aad(&dupdate);
	}

	CRYPTO_TRACE("authenc ret 0x%" PRIx32, ret);
	return ret;
}

/*
 * Update payload part of the authenc operation
 *
 * @ctx        Reference the API context pointer
 * @data       Data to authenticate and encrypt/decrypt
 * @len        Length of the input data and output result
 * @dst        [out] Output data of the operation
 */
static TEE_Result authenc_update_payload(struct crypto_authenc_ctx *ctx,
					 TEE_OperationMode mode,
					 const uint8_t *data,
					 size_t len, uint8_t *dst)
{
	TEE_Result ret = TEE_ERROR_NOT_IMPLEMENTED;
	struct crypto_authenc *authenc = to_authenc_ctx(ctx);

	if (!dst) {
		CRYPTO_TRACE("Destination buffer error");
		return TEE_ERROR_BAD_PARAMETERS;
	}

	if (!data && len) {
		CRYPTO_TRACE("Bad data @%p-%zu bytes", data, len);
		return TEE_ERROR_BAD_PARAMETERS;
	}

	if (authenc->op && authenc->op->update_payload) {
		struct drvcrypt_authenc_update_payload dupdate = {
			.ctx = authenc->ctx,
			.encrypt = (mode == TEE_MODE_ENCRYPT),
			.src.data = (uint8_t *)data,
			.src.length = len,
			.dst.data = dst,
			.dst.length = len,
		};

		ret = authenc->op->update_payload(&dupdate);
	}

	CRYPTO_TRACE("authenc ret 0x%" PRIx32, ret);
	return ret;
}

/*
 * Last block for the authenc encrypt and get tag operation
 *
 * @ctx     Reference the API context pointer
 * @data    Data to authenticate and encrypt (can be NULL)
 * @len     Length of the input data and output result (can be 0)
 * @dst     [out] Output data of the operation
 * @tag     [out] Output tag of the operation
 * @tag_len [in/out] in: size of the dst_tag buffer
 *                  out: size of the computed tag
 */
static TEE_Result authenc_enc_final(struct crypto_authenc_ctx *ctx,
				    const uint8_t *data, size_t len,
				    uint8_t *dst, uint8_t *tag,
				    size_t *tag_len)
{
	TEE_Result ret = TEE_ERROR_NOT_IMPLEMENTED;
	struct crypto_authenc *authenc = to_authenc_ctx(ctx);

	if (!dst && len) {
		CRYPTO_TRACE("Bad output @%p-%zu bytes", dst, len);
		return TEE_ERROR_BAD_PARAMETERS;
	}

	if (!data && len) {
		CRYPTO_TRACE("Bad input @%p-%zu bytes", data, len);
		return TEE_ERROR_BAD_PARAMETERS;
	}

	if (authenc->op && authenc->op->enc_final) {
		struct drvcrypt_authenc_final dfinal = {
			.ctx = authenc->ctx,
			.src.data = (uint8_t *)data,
			.src.length = len,
			.dst.data = dst,
			.dst.length = len,
			.tag.data = tag,
			.tag.length = *tag_len
		};

		ret = authenc->op->enc_final(&dfinal);
		if (ret == TEE_SUCCESS)
			*tag_len = dfinal.tag.length;
	}

	CRYPTO_TRACE("authenc ret 0x%" PRIx32, ret);
	return ret;
}

/*
 * Last block for the authenc decrypt and check tag operation
 *
 * @ctx         Reference the API context pointer
 * @src_data    Data to authenticate and encrypt (can be NULL)
 * @len         Length of the input data and output result (can be 0)
 * @dst         [out] Output data of the operation
 * @tag         Tag to check at end of operation
 * @tag_len     Length of @tag
 */
static TEE_Result authenc_dec_final(struct crypto_authenc_ctx *ctx,
				    const uint8_t *data, size_t len,
				    uint8_t *dst, const uint8_t *tag,
				    size_t tag_len)
{
	TEE_Result ret = TEE_ERROR_NOT_IMPLEMENTED;
	struct crypto_authenc *authenc = to_authenc_ctx(ctx);

	if (!dst && len) {
		CRYPTO_TRACE("Bad output @%p-%zu bytes", dst, len);
		return TEE_ERROR_BAD_PARAMETERS;
	}

	if (!data && len) {
		CRYPTO_TRACE("Bad data @%p-%zu bytes", data, len);
		return TEE_ERROR_BAD_PARAMETERS;
	}

	if (authenc->op && authenc->op->dec_final) {
		struct drvcrypt_authenc_final dfinal = {
			.ctx = authenc->ctx,
			.src.data = (uint8_t *)data,
			.src.length = len,
			.dst.data = dst,
			.dst.length = len,
			.tag.data = (uint8_t *)tag,
			.tag.length = tag_len
		};

		ret = authenc->op->dec_final(&dfinal);
	}

	CRYPTO_TRACE("authenc ret 0x%" PRIx32, ret);
	return ret;
}

/*
 * Finalize the authenc operation
 *
 * @ctx   Reference the API context pointer
 */
static void authenc_final(struct crypto_authenc_ctx *ctx)
{
	struct crypto_authenc *authenc = to_authenc_ctx(ctx);

	if (authenc->op && authenc->op->final)
		authenc->op->final(authenc->ctx);
}

static const struct crypto_authenc_ops authenc_ops = {
	.init = authenc_init,
	.update_aad = authenc_update_aad,
	.update_payload = authenc_update_payload,
	.enc_final = authenc_enc_final,
	.dec_final = authenc_dec_final,
	.final = authenc_final,
	.free_ctx = authenc_free_ctx,
	.copy_state = authenc_copy_state,
};

TEE_Result drvcrypt_authenc_alloc_ctx(struct crypto_authenc_ctx **ctx,
				      uint32_t algo)
{
	TEE_Result ret = TEE_ERROR_NOT_IMPLEMENTED;
	struct crypto_authenc *authenc = NULL;

	CRYPTO_TRACE("authenc alloc_ctx algo 0x%" PRIx32, algo);

	assert(ctx);

	authenc = calloc(1, sizeof(*authenc));
	if (!authenc)
		return TEE_ERROR_OUT_OF_MEMORY;

	authenc->op = drvcrypt_get_ops(CRYPTO_AUTHENC);
	if (authenc->op && authenc->op->alloc_ctx)
		ret = authenc->op->alloc_ctx(&authenc->ctx, algo);

	if (ret != TEE_SUCCESS) {
		free(authenc);
	} else {
		authenc->authenc_ctx.ops = &authenc_ops;
		*ctx = &authenc->authenc_ctx;
	}

	CRYPTO_TRACE("authenc alloc_ctx ret 0x%" PRIx32, ret);
	return ret;
}

/* SPDX-License-Identifier: BSD-2-Clause */
/*
 * Copyright (c) 2021, STMicroelectronics - All Rights Reserved
 *
 * Authenticated Encryption interface calling the crypto driver
 */
#ifndef __DRVCRYPT_AUTHENC_H__
#define __DRVCRYPT_AUTHENC_H__

#include <crypto/crypto_impl.h>
#include <tee_api_types.h>

/*
 * Authenticated Encryption operation context
 */
struct crypto_authenc {
	struct crypto_authenc_ctx authenc_ctx;	/* Crypto authenc API context */
	void *ctx;				/* Authenc context */
	struct drvcrypt_authenc *op;		/* Reference to the operation */
};

/*
 * Authenticated Encryption algorithm initialization data
 */
struct drvcrypt_authenc_init {
	void *ctx;		     /* Software context */
	bool encrypt;		     /* Encrypt or decrypt direction */
	struct drvcrypt_buf key;     /* First key */
	struct drvcrypt_buf nonce;   /* Nonce */
	size_t tag_len;		     /* Tag length  */
	size_t aad_len;		     /* Additional Authenticated Data length */
	size_t payload_len;	     /* Payload length */
};

/*
 * Authenticated Encryption algorithm update_aad data
 */
struct drvcrypt_authenc_update_aad {
	void *ctx;		 /* Software context */
	bool encrypt;		 /* Encrypt or decrypt direction */
	struct drvcrypt_buf aad; /* Additional Authenticated Data buffer */
};

/*
 * Authenticated Encryption algorithm update_aad data
 */
struct drvcrypt_authenc_update_payload {
	void *ctx;		 /* Software context */
	bool encrypt;		 /* Encrypt or decrypt direction */
	struct drvcrypt_buf src; /* Buffer source (message or cipher) */
	struct drvcrypt_buf dst; /* Buffer destination (cipher or message) */
};

/*
 * Authenticated Encryption algorithm final data
 */
struct drvcrypt_authenc_final {
	void *ctx;		 /* Software context */
	bool encrypt;		 /* Encrypt or decrypt direction */
	struct drvcrypt_buf src; /* Buffer source (message or cipher) */
	struct drvcrypt_buf dst; /* Buffer destination (cipher or message) */
	struct drvcrypt_buf tag; /* Tag buffer */
};

/*
 * Crypto library authenc driver operations
 */
struct drvcrypt_authenc {
	/* Allocate context */
	TEE_Result (*alloc_ctx)(void **ctx, uint32_t algo);
	/* Free context */
	void (*free_ctx)(void *ctx);
	/* Initialize the authenc operation */
	TEE_Result (*init)(struct drvcrypt_authenc_init *dinit);
	/* Update the authenc operation with associated data */
	TEE_Result (*update_aad)(struct drvcrypt_authenc_update_aad *dupdate);
	/* Update the authenc operation with payload data */
	TEE_Result (*update_payload)(struct drvcrypt_authenc_update_payload *d);
	/* Update (or not) with payload data and get tag for encrypt op. */
	TEE_Result (*enc_final)(struct drvcrypt_authenc_final *dfinal);
	/* Update (or not) with payload data and verify tag for decrypt op. */
	TEE_Result (*dec_final)(struct drvcrypt_authenc_final *dfinal);
	/* Finalize the authenc operation */
	void (*final)(void *ctx);
	/* Copy authenc context */
	void (*copy_state)(void *dst_ctx, void *src_ctx);
};

/*
 * Register an authenc processing driver in the crypto API
 *
 * @ops - Driver operations
 */
static inline TEE_Result drvcrypt_register_authenc(struct drvcrypt_authenc *ops)
{
	return drvcrypt_register(CRYPTO_AUTHENC, (void *)ops);
}

#endif /* __DRVCRYPT_AUTHENC_H__ */

/* SPDX-License-Identifier: BSD-2-Clause */
/*
 * Copyright 2018-2020 NXP
 *
 * Definition of the functions shared locally.
 */
#ifndef __LOCAL_H__
#define __LOCAL_H__

#include <drvcrypt_acipher.h>

/*
 * Mask Generation function. Use a Hash operation
 * to generate an output @mask from an input @seed
 *
 * @mgf_data  [in/out] MGF data
 */
TEE_Result drvcrypt_rsa_mgf1(struct drvcrypt_rsa_mgf *mgf_data);

/*
 * PKCS#1 - Signature of RSA message and encodes the signature.
 *
 * @ssa_data   [in/out] RSA data to sign / Signature
 */
TEE_Result drvcrypt_rsassa_sign(struct drvcrypt_rsa_ssa *ssa_data);

/*
 * PKCS#1 - Verification the encoded signature of RSA message.
 *
 * @ssa_data   RSA Encoded signature data
 */
TEE_Result drvcrypt_rsassa_verify(struct drvcrypt_rsa_ssa *ssa_data);

#endif /* __LOCAL_H__ */

/* SPDX-License-Identifier: BSD-2-Clause */
/*
 * Copyright 2018-2020 NXP
 *
 * Cipher interface calling the crypto driver.
 */
#ifndef __DRVCRYPT_CIPHER_H__
#define __DRVCRYPT_CIPHER_H__

#include <crypto/crypto_impl.h>
#include <tee_api_types.h>

/*
 * Cipher operation context
 */
struct crypto_cipher {
	struct crypto_cipher_ctx cipher_ctx; /* Crypto cipher API context */
	void *ctx;                           /* Cipher context */
	struct drvcrypt_cipher *op;          /* Reference to the operation */
};

/*
 * Cipher algorithm initialization data
 */
struct drvcrypt_cipher_init {
	void *ctx;		  /* Software context */
	bool encrypt;		  /* Encrypt or decrypt direction */
	struct drvcrypt_buf key1; /* First key */
	struct drvcrypt_buf key2; /* Second key */
	struct drvcrypt_buf iv;	  /* Initial vector */
};

/*
 * Cipher algorithm update data
 */
struct drvcrypt_cipher_update {
	void *ctx;		 /* Software context */
	bool encrypt;		 /* Encrypt or decrypt direction */
	bool last;		 /* Last block to handle */
	struct drvcrypt_buf src; /* Buffer source (message or cipher) */
	struct drvcrypt_buf dst; /* Buffer dest (message or cipher) */
};

/*
 * Crypto library cipher driver operations
 */
struct drvcrypt_cipher {
	/* Allocate context */
	TEE_Result (*alloc_ctx)(void **ctx, uint32_t algo);
	/* Free context */
	void (*free_ctx)(void *ctx);
	/* Initialize the cipher operation */
	TEE_Result (*init)(struct drvcrypt_cipher_init *dinit);
	/* Update the cipher operation */
	TEE_Result (*update)(struct drvcrypt_cipher_update *dupdate);
	/* Finalize the cipher operation */
	void (*final)(void *ctx);
	/* Copy cipher context */
	void (*copy_state)(void *dst_ctx, void *src_ctx);
};

/*
 * Register a cipher processing driver in the crypto API
 *
 * @ops - Driver operations
 */
static inline TEE_Result drvcrypt_register_cipher(struct drvcrypt_cipher *ops)
{
	return drvcrypt_register(CRYPTO_CIPHER, (void *)ops);
}

#endif /* __DRVCRYPT_CIPHER_H__ */

/* SPDX-License-Identifier: BSD-2-Clause */
/*
 * Copyright 2018-2021 NXP
 *
 * Brief   Asymmetric Cipher interface calling the HW crypto driver.
 */
#ifndef __DRVCRYPT_ACIPHER_H__
#define __DRVCRYPT_ACIPHER_H__

#include <crypto/crypto.h>
#include <tee_api_types.h>

/*
 * Assymetric Cipher RSA Algorithm enumerate
 */
enum drvcrypt_rsa_id {
	DRVCRYPT_RSA_NOPAD = 0,	   /* RSA Algo mode NO PAD */
	DRVCRYPT_RSA_OAEP,	   /* RSA Algo mode OAEP */
	DRVCRYPT_RSA_PKCS_V1_5,	   /* RSA Algo mode PKCSv1.5 */
	DRVCRYPT_RSASSA_PKCS_V1_5, /* RSA Signature Algo mode PKCSv1.5 */
	DRVCRYPT_RSASSA_PSS,	   /* RSA Signature Algo mode PSS */
};

/*
 * RSA Key object
 */
struct drvcrypt_rsakey {
	void *key;	/* Public or Private key */
	size_t n_size;	/* Size in bytes of the Modulus N */
	bool isprivate; /* True if private key */
};

/*
 * RSA Mask Generation data
 */
struct drvcrypt_rsa_mgf {
	uint32_t hash_algo;	  /* HASH Algorithm */
	size_t digest_size;	  /* Hash Digest Size */
	struct drvcrypt_buf seed; /* Seed to generate mask */
	struct drvcrypt_buf mask; /* Mask generated */
};

/*
 * RSA Encoded Signature data
 */
struct drvcrypt_rsa_ssa {
	uint32_t algo;		       /* Operation algorithm */
	uint32_t hash_algo;	       /* HASH Algorithm */
	size_t digest_size;	       /* Hash Digest Size */
	struct drvcrypt_rsakey key;    /* Public or Private Key */
	struct drvcrypt_buf message;   /* Message to sign or signed */
	struct drvcrypt_buf signature; /* Signature of the message */
	size_t salt_len;	       /* Signature Salt length */

	/* RSA Mask Generation function */
	TEE_Result (*mgf)(struct drvcrypt_rsa_mgf *mgf_data);
};

/*
 * RSA Encrypt/Decript data
 */
struct drvcrypt_rsa_ed {
	enum drvcrypt_rsa_id rsa_id; /* RSA Algorithm Id */
	uint32_t hash_algo;	     /* HASH Algorithm */
	size_t digest_size;	     /* Hash Digest Size */
	struct drvcrypt_rsakey key;  /* Public or Private key */
	struct drvcrypt_buf message; /* Message to encrypt or decrypted */
	struct drvcrypt_buf cipher;  /* Cipher encrypted or to decrypt */
	struct drvcrypt_buf label;   /* Additional Label (RSAES) */

	/* RSA Mask Generation function */
	TEE_Result (*mgf)(struct drvcrypt_rsa_mgf *mgf_data);
};

/*
 * Crypto Library RSA driver operations
 */
struct drvcrypt_rsa {
	/* Allocates the RSA keypair */
	TEE_Result (*alloc_keypair)(struct rsa_keypair *key, size_t size_bits);
	/* Allocates the RSA public key */
	TEE_Result (*alloc_publickey)(struct rsa_public_key *key,
				      size_t size_bits);
	/* Free RSA public key */
	void (*free_publickey)(struct rsa_public_key *key);
	/* Free RSA keypair */
	void (*free_keypair)(struct rsa_keypair *key);
	/* Generates the RSA keypair */
	TEE_Result (*gen_keypair)(struct rsa_keypair *key, size_t size_bits);

	/* RSA Encryption */
	TEE_Result (*encrypt)(struct drvcrypt_rsa_ed *rsa_data);
	/* RSA Decryption */
	TEE_Result (*decrypt)(struct drvcrypt_rsa_ed *rsa_data);

	struct {
		/* RSA Sign a message and encode the signature */
		TEE_Result (*ssa_sign)(struct drvcrypt_rsa_ssa *ssa_data);
		/* RSA Encoded Signature Verification */
		TEE_Result (*ssa_verify)(struct drvcrypt_rsa_ssa *ssa_data);
	} optional;
};

/*
 * Register a RSA processing driver in the crypto API
 *
 * @ops - Driver operations in the HW layer
 */
static inline TEE_Result drvcrypt_register_rsa(const struct drvcrypt_rsa *ops)
{
	return drvcrypt_register(CRYPTO_RSA, (void *)ops);
}

/*
 * Signature data
 */
struct drvcrypt_sign_data {
	uint32_t algo;               /* Operation algorithm */
	void *key;                   /* Public or Private Key */
	size_t size_sec;             /* Security size in bytes */
	struct drvcrypt_buf message;    /* Message to sign or signed */
	struct drvcrypt_buf signature;  /* Signature of the message */
};

/*
 * Shared Secret data
 */
struct drvcrypt_secret_data {
	void *key_priv;		    /* Private Key */
	void *key_pub;		    /* Public Key */
	size_t size_sec;	    /* Security size in bytes */
	struct drvcrypt_buf secret; /* Shared secret */
};

/*
 * Crypto ECC driver operations
 */
struct drvcrypt_ecc {
	/* Allocates the ECC keypair */
	TEE_Result (*alloc_keypair)(struct ecc_keypair *key, size_t size_bits);
	/* Allocates the ECC public key */
	TEE_Result (*alloc_publickey)(struct ecc_public_key *key,
				      size_t size_bits);
	/* Free ECC public key */
	void (*free_publickey)(struct ecc_public_key *key);
	/* Generates the ECC keypair */
	TEE_Result (*gen_keypair)(struct ecc_keypair *key, size_t size_bytes);
	/* ECC Sign a message and returns the signature */
	TEE_Result (*sign)(struct drvcrypt_sign_data *sdata);
	/* ECC Verify a message's signature */
	TEE_Result (*verify)(struct drvcrypt_sign_data *sdata);
	/* ECC Shared Secret */
	TEE_Result (*shared_secret)(struct drvcrypt_secret_data *sdata);
};

/*
 * Register an ECC processing driver in the crypto API
 *
 * @ops - Driver operations in the HW layer
 */
static inline TEE_Result drvcrypt_register_ecc(struct drvcrypt_ecc *ops)
{
	return drvcrypt_register(CRYPTO_ECC, (void *)ops);
}

/*
 * Crypto Library DH driver operations
 */
struct drvcrypt_dh {
	/* Allocates the DH keypair */
	TEE_Result (*alloc_keypair)(struct dh_keypair *key, size_t size_bits);
	/* Generates the DH keypair */
	TEE_Result (*gen_keypair)(struct dh_keypair *key, struct bignum *q,
				  size_t size_bits);
	/* DH Shared Secret */
	TEE_Result (*shared_secret)(struct drvcrypt_secret_data *sdata);
};

/*
 * Register a DH processing driver in the crypto API
 *
 * @ops - Driver operations in the HW layer
 */
static inline TEE_Result drvcrypt_register_dh(struct drvcrypt_dh *ops)
{
	return drvcrypt_register(CRYPTO_DH, (void *)ops);
}

/*
 * Crypto Library DSA driver operations
 */
struct drvcrypt_dsa {
	/* Allocates the DSA keypair */
	TEE_Result (*alloc_keypair)(struct dsa_keypair *key, size_t l_bits,
				    size_t n_bits);
	/* Allocates the DSA public key */
	TEE_Result (*alloc_publickey)(struct dsa_public_key *key, size_t l_bits,
				      size_t n_bits);
	/* Generates the DSA keypair */
	TEE_Result (*gen_keypair)(struct dsa_keypair *key, size_t l_bits,
				  size_t n_bits);
	/* DSA Sign a message and returns the signature */
	TEE_Result (*sign)(struct drvcrypt_sign_data *sdata, size_t l_bytes,
			   size_t n_bytes);
	/* DSA Verify a message's signature */
	TEE_Result (*verify)(struct drvcrypt_sign_data *sdata, size_t l_bytes,
			     size_t n_bytes);
};

/*
 * Register a DSA processing driver in the crypto API
 *
 * @ops - Driver operations in the HW layer
 */
static inline TEE_Result drvcrypt_register_dsa(struct drvcrypt_dsa *ops)
{
	return drvcrypt_register(CRYPTO_DSA, (void *)ops);
}

