            if ((err = ccm_process(&ccm, (unsigned char*)tests[x].pt, tests[x].ptlen, buf, CCM_ENCRYPT)) != CRYPT_OK) {
               return err;
            }
            if ((err = ccm_done(&ccm, tag, &taglen)) != CRYPT_OK) {
               return err;
            }
         }

